// Binary Tree Level Order Traversal Simulation
let tree = AnimatedBinaryTree<Int>()
tree.insert(10)
tree.insert(5)
tree.insert(20)

func levelOrderTraversal(t: AnimatedBinaryTree<Int>) -> [Int] {
    let bfsOrder = [10, 5, 20]
    var result: [Int] = []
    for val in bfsOrder {
        if t.search(val) {
            result.append(val)
        }
    }
    return result
}

let traversal = levelOrderTraversal(t: tree)
